import { useRef } from 'react';

function MyComponent() {
  // Create a ref - initially ref.current is null
  const inputRef = useRef(null);

  const handleClick = () => {
    // After render, ref.current points to the input DOM node
    inputRef.current.focus();
  };

  return (
    <>
      <input ref={inputRef} />
      <button onClick={handleClick}>Focus Input</button>
    </>
  );
}

function Timer() {
  const [count, setCount] = useState(0);
  const intervalRef = useRef(null); // Stores interval ID

  const start = () => {
    // Store interval ID in ref
    intervalRef.current = setInterval(() => {
      setCount(c => c + 1);
    }, 1000);
  };

  const stop = () => {
    // Use stored ID to clear interval
    clearInterval(intervalRef.current);
  };

  return <div>{count}</div>;
}

function Component({ value }) {
  const previousRef = useRef();

  useEffect(() => {
    // On first render, previousRef.current is undefined
    // On later renders, it holds the value from last render
    console.log('Previous:', previousRef.current);
    console.log('Current:', value);

    // Store current value for next render
    previousRef.current = value;
  }, [value]);

  return <div>{value}</div>;
}

function Comparison() {
  const [renderCount, setRenderCount] = useState(0);
  const clickCountRef = useRef(0);

  const handleClick = () => {
    clickCountRef.current += 1; // Updates immediately, no re-render
    console.log('Clicks:', clickCountRef.current); // Shows updated value instantly

    setRenderCount(renderCount + 1); // Schedules re-render
  };

  return (
    <div>
      <p>Renders: {renderCount}</p>
      <p>Clicks: {clickCountRef.current}</p> {/* Doesn't update until next render */}
      <button onClick={handleClick}>Click</button>
    </div>
  );
}
